class Solution { fun getAllElements(root1:TreeNode?,root2:TreeNode?):List<Int>{val first=mutableListOf<Int>();val second=mutableListOf<Int>();fun inorder(node:TreeNode?,values:MutableList<Int>){node?:return;inorder(node.left,values);values.add(node.`val`);inorder(node.right,values)};inorder(root1,first);inorder(root2,second);val answer=mutableListOf<Int>();var i=0;var j=0;while(i<first.size||j<second.size)if(j==second.size||i<first.size&&first[i]<=second[j])answer.add(first[i++])else answer.add(second[j++]);return answer} }
